'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { supabase } from '@/lib/supabase/client';
import DiagnosticQuestion from '@/components/DiagnosticQuestion';
import DiagnosticProgress from '@/components/DiagnosticProgress';

interface DiagnosticOption {
  value: string;
  label: string;
}

interface DiagnosticQuestionData {
  id: string;
  question: string;
  question_type: string;
  options: DiagnosticOption[] | null;
  order_index: number;
}

interface SessionData {
  id: string;
  error_id: string;
  context_id: string;
  answers: Record<string, unknown>;
  status: string;
}

export default function DiagnosePage() {
  const params = useParams();
  const router = useRouter();

  const sessionId = params?.sessionId as string | undefined;

  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [questions, setQuestions] = useState<DiagnosticQuestionData[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, unknown>>({});
  const [loading, setLoading] = useState(true);
  const [pageError, setPageError] = useState<string | null>(null);

  useEffect(() => {
    if (!sessionId) return;

    const fetchDiagnosis = async () => {
      setLoading(true);
      setPageError(null);

      const { data: session, error: sessionError } = await supabase
        .from('diagnostic_sessions')
        .select('*')
        .eq('id', sessionId)
        .single();

      if (sessionError || !session) {
        console.error('Erro ao carregar sessão:', sessionError);

        setPageError(
          sessionError?.message || 'Sessão de diagnóstico não encontrada.'
        );

        setLoading(false);
        return;
      }

      const { data: questionData, error: questionError } = await supabase
        .from('diagnostic_questions')
        .select(
          'id, question, question_type, options, order_index'
        )
        .eq('context_id', session.context_id)
        .order('order_index', { ascending: true });

      if (questionError) {
        console.error('Erro ao carregar perguntas:', questionError);

        setPageError(
          questionError.message ||
            'Não foi possível carregar as perguntas.'
        );

        setLoading(false);
        return;
      }

      setSessionData(session);
      setQuestions(questionData ?? []);
      setAnswers(session.answers ?? {});
      setLoading(false);
    };

    fetchDiagnosis();
  }, [sessionId]);

  const handleAnswer = async (answer: DiagnosticOption) => {
    if (!sessionData) return;

    const currentQuestion = questions[currentQuestionIndex];

    if (!currentQuestion) return;

    const nextAnswers = {
      ...answers,
      [currentQuestion.id]: answer,
    };

    setAnswers(nextAnswers);

    const { error } = await supabase
      .from('diagnostic_sessions')
      .update({
        answers: nextAnswers,
        status:
          currentQuestionIndex + 1 >= questions.length
            ? 'completed'
            : 'in_progress',
      })
      .eq('id', sessionData.id);

    if (error) {
      console.error('Erro ao salvar resposta:', error);
      setPageError('Não foi possível salvar sua resposta.');
      return;
    }

    if (currentQuestionIndex + 1 < questions.length) {
      setCurrentQuestionIndex((previous) => previous + 1);
    } else {
      setCurrentQuestionIndex(questions.length);
    }
  };

  if (loading) {
    return (
      <main className="min-h-screen bg-slate-50 px-6 py-16">
        <div className="mx-auto max-w-3xl">
          <div className="animate-pulse">
            <div className="h-4 w-32 rounded bg-slate-200" />
            <div className="mt-6 h-10 w-3/4 rounded bg-slate-200" />
            <div className="mt-10 h-64 rounded-3xl bg-white shadow-sm" />
          </div>
        </div>
      </main>
    );
  }

  if (pageError) {
    return (
      <main className="min-h-screen bg-slate-50 px-6 py-16">
        <div className="mx-auto max-w-2xl rounded-3xl border border-red-200 bg-white p-8 text-center shadow-sm">
          <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-red-50 text-red-600">
            !
          </div>

          <h1 className="mt-5 text-2xl font-black text-slate-950">
            Não foi possível continuar
          </h1>

          <p className="mt-3 text-slate-600">
            {pageError}
          </p>

          <button
            onClick={() => router.back()}
            className="mt-7 rounded-xl bg-slate-950 px-5 py-3 font-bold text-white"
          >
            Voltar
          </button>
        </div>
      </main>
    );
  }

  if (!sessionData) {
    return null;
  }

  const diagnosisFinished =
    currentQuestionIndex >= questions.length;

  return (
    <main className="min-h-[calc(100vh-80px)] bg-slate-50 px-6 py-12">
      <div className="mx-auto max-w-3xl">

        <button
          onClick={() => router.back()}
          className="text-sm font-bold text-slate-500 hover:text-blue-600"
        >
          ← Voltar
        </button>

        <div className="mt-8">
          <p className="text-sm font-black uppercase tracking-[0.2em] text-blue-600">
            Diagnóstico
          </p>

          <h1 className="mt-3 text-3xl font-black tracking-tight text-slate-950 sm:text-4xl">
            Vamos entender o que está acontecendo
          </h1>

          <p className="mt-4 text-lg leading-8 text-slate-600">
            Responda algumas perguntas para encontrarmos o caminho
            mais adequado para o seu problema.
          </p>
        </div>

        <div className="mt-8">
          <DiagnosticProgress
            currentQuestionIndex={
              diagnosisFinished
                ? questions.length
                : currentQuestionIndex
            }
            totalQuestions={questions.length}
          />
        </div>

        {questions.length === 0 ? (
          <div className="mt-8 rounded-3xl border border-amber-200 bg-amber-50 p-7">
            <h2 className="font-extrabold text-amber-900">
              Diagnóstico ainda não configurado
            </h2>

            <p className="mt-2 text-sm leading-6 text-amber-800">
              Este contexto foi encontrado, mas ainda não possui
              perguntas cadastradas.
            </p>
          </div>
        ) : diagnosisFinished ? (
          <div className="mt-8 rounded-3xl border border-emerald-200 bg-white p-8 shadow-sm">
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-50 text-emerald-600">
              ✓
            </div>

            <h2 className="mt-5 text-2xl font-black text-slate-950">
              Diagnóstico inicial concluído
            </h2>

            <p className="mt-3 leading-7 text-slate-600">
              Suas respostas foram registradas. A próxima etapa
              será analisar as respostas e indicar a solução mais
              adequada.
            </p>
          </div>
        ) : (
          <div className="mt-8 rounded-3xl border border-slate-200 bg-white p-7 shadow-sm sm:p-9">
            <p className="text-sm font-bold text-slate-400">
              Pergunta {currentQuestionIndex + 1} de {questions.length}
            </p>

            <div className="mt-6">
              <DiagnosticQuestion
                question={{
                  title: questions[currentQuestionIndex].question,
                  options:
                    questions[currentQuestionIndex].options ?? [],
                }}
                onAnswer={handleAnswer}
              />
            </div>
          </div>
        )}
      </div>
    </main>
  );
}